private val q = scala.collection.mutable.Queue[Int]()

def take(): Int = synchronized {
    while (q.isEmpty) wait()        // releases the monitor, re-acquires on wake
    q.dequeue()
}

def put(v: Int): Unit = synchronized {
    q.enqueue(v)                    // change state first
    notifyAll()                     // then wake the wait set
}

